<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/dependencies';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import DagView from '../components/DagView.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const id=ref('demo-package'),predecessor=ref('T01'),successor=ref('T05');const pkg=computed(()=>props.data.packages.find(p=>p.id===id.value)||props.data.packages[0]);const edges=computed(()=>props.data.dependencies.filter(d=>d.package_id===pkg.value?.id));const{busy,error,notice,act}=useAction();watch(()=>pkg.value?.id,()=>{predecessor.value=pkg.value?.tasks[0].task_id||'';successor.value=pkg.value?.tasks[1]?.task_id||''});</script><template><Heading index="03 / FINISH–START DAG" title="每条依赖，只表达先后。" detail="零等待finish-start；未知任务、自环、重复边与环拒绝。没有资源、日历或人员约束。"/><label class="selector">依赖工作包<select aria-label="依赖工作包" v-model="id"><option v-for="p in data.packages" :key="p.id" :value="p.id">{{p.name}}</option></select></label><section v-if="pkg" class="diagram-section"><h2>工作包FS拓扑</h2><DagView :tasks="pkg.tasks" :edges="edges.map(e=>[e.predecessor,e.successor])"/></section><section v-if="canWrite&&pkg" class="form-section"><h2>添加一条FS依赖</h2><form class="form-grid" @submit.prevent="act(async()=>{await create({package_id:pkg!.id,predecessor,successor});await refresh()},'依赖已通过DAG检查并保存，已有快照保持原样')"><label>前置任务<select aria-label="前置任务" v-model="predecessor"><option v-for="t in pkg.tasks" :key="t.task_id" :value="t.task_id">{{t.task_id}} {{t.name}}</option></select></label><label>后续任务<select aria-label="后续任务" v-model="successor"><option v-for="t in pkg.tasks" :key="t.task_id" :value="t.task_id">{{t.task_id}} {{t.name}}</option></select></label><button class="primary" :disabled="busy">校验并添加FS依赖</button></form><Notice :error="error" :notice="notice"/></section><details><summary>逐边FS依赖台账 · {{edges.length}}条</summary><div class="table-scroll"><table><thead><tr><th>前置</th><th>后续</th><th>关系</th></tr></thead><tbody><tr v-for="e in edges" :key="e.id"><td>{{e.predecessor}}</td><td>{{e.successor}}</td><td>finish-start / 0h等待</td></tr></tbody></table></div></details></template>